using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class CreationBookChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  var historical=new SliceState();string before=JsonUtility.ToJson(historical);foreach(CreationBookSection section in Enum.GetValues(typeof(CreationBookSection)))for(int i=0;i<20;i++)CreationBookText.Read(historical,section,i);Require(JsonUtility.ToJson(historical)==before,"Reading initialized or changed historical state");Require(CreationBookText.Read(historical,CreationBookSection.Places,1).text.Contains("unknown"),"Unknown history presented as established facts");
  var state=new SliceState();var person=state.Social(0);person.trust=.8f;person.musicGatherings=2;person.RememberPlace(0,true,0);person.Place(0).requests=3;person.Place(0).answers=1;state.Resources.wood=7;state.Resources.wheat=11;state.Resources.freshFood=2;state.Hybrid.time=20;state.Hybrid.Evidence.Add(20,EvidenceKind.Provision,EvidenceSource.PlayerPlacement,CreatureAction.IdleOrObserve,"wood-gift","2 supplies");
  before=JsonUtility.ToJson(state);var people=CreationBookText.Read(state,CreationBookSection.People,0);var stocks=CreationBookText.Read(state,CreationBookSection.Provisions);var place=CreationBookText.Read(state,CreationBookSection.Places);var evidence=CreationBookText.Read(state,CreationBookSection.Places,1);
  Require(people.count==12&&people.text.Contains("80%")&&people.text.Contains("Music visits 2"),"People profile does not match actual memory");Require(stocks.text.Contains("Wood 7 / 36")&&stocks.text.Contains("Food stored 13 / 48"),"Stocks do not match resource state");Require(place.text.Contains("person-visits 1")&&place.text.Contains("Requests 3 · Accepted 1")&&place.text.Contains("contributors: unknown"),"Place totals or honest attribution missing");Require(evidence.text.Contains("Player · Gift")&&evidence.text.Contains("Wood gift")&&!evidence.text.Contains("Creature · Gift"),"Player intervention credited to creature");
  for(int i=0;i<110;i++)state.Hybrid.Evidence.Add(20,EvidenceKind.ActionCompleted,EvidenceSource.Autonomous,CreatureAction.PlayWithToy,"object-12","Outcome confirmed");Require(state.Hybrid.evidence.events.Length==96,"Evidence bound changed");before=JsonUtility.ToJson(state);for(int i=0;i<100;i++)foreach(CreationBookSection section in Enum.GetValues(typeof(CreationBookSection)))CreationBookText.Read(state,section,i);Require(before==JsonUtility.ToJson(state),"Book projections mutated populated state");Require(JsonUtility.FromJson<SliceState>(before).Valid(),"Recorded evidence save failed");
  Debug.Log("BWVR_CREATION_BOOK_MODEL_PASS: exact stock/profile/place data, unknown history, player attribution, bounded evidence, repeated pure reads, save round trip");
 }
 public static void VerifyRuntime()=>VerifyWithCapture(null);
 public static void VerifyWithCapture(Action<QuestSlice,CreationBookSection> capture){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var stateField=typeof(QuestSlice).GetField("state",flags);var original=(SliceState)stateField.GetValue(slice);var panel=(GameObject)typeof(QuestSlice).GetField("panel",flags).GetValue(slice);bool wasPanel=panel.activeSelf;var test=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(original));test.paused=false;test.Hybrid.Evidence.Add(test.Hybrid.time,EvidenceKind.ActionCompleted,EvidenceSource.PlayerGuidance,CreatureAction.RespondToGuidance,new string('x',160),new string('y',160));test.Hybrid.Evidence.Add(test.Hybrid.time,EvidenceKind.Provision,EvidenceSource.PlayerPlacement,CreatureAction.IdleOrObserve,"wood-gift",new string('z',160));stateField.SetValue(slice,test);var root=(GameObject)typeof(QuestSlice).GetField("creationBook",flags).GetValue(slice);var pointer=typeof(QuestSlice).GetMethod("BookPointer",flags);var audio=typeof(QuestSlice).GetMethod("ShowAudioSettings",flags);var body=(UnityEngine.UI.Text)typeof(QuestSlice).GetField("bookBody",flags).GetValue(slice);int calls=0;var outsider=new GameObject("QA outside book action",typeof(BoxCollider),typeof(SpatialTarget));outsider.GetComponent<SpatialTarget>().invoke=()=>calls++;
  try{
   Require(!slice.CreationBookOpen,"Book did not start hidden");string before=JsonUtility.ToJson(test);Require(root.GetComponentsInChildren<Collider>(true).All(c=>c.isTrigger),"Book UI introduced solid simulation obstacles");Require(slice.ShowCreationBook(true)&&slice.CreationBookOpen,"Book did not open");Require(before==JsonUtility.ToJson(test),"Opening Book changed pause or gameplay state");
   foreach(CreationBookSection section in Enum.GetValues(typeof(CreationBookSection))){slice.SelectCreationBook(section);var initial=CreationBookText.Read(test,section);for(int i=0;i<initial.count;i++){Canvas.ForceUpdateCanvases();Require(body.preferredHeight<=body.rectTransform.rect.height+1,"Book text overflows: "+section+" / "+i+" ("+body.preferredHeight+")");capture?.Invoke(slice,section);slice.TurnCreationBook(1);}}
   Require(before==JsonUtility.ToJson(test),"Book navigation/refresh changed simulation state");
   Require((bool)pointer.Invoke(slice,new object[]{1,true,false,outsider.GetComponent<Collider>(),true})&&calls==0,"Book pointer allowed world action");var next=root.GetComponentsInChildren<SpatialTarget>().First(t=>t.name=="Next");Physics.SyncTransforms();var ray=new Ray(next.transform.position-root.transform.forward*.2f,root.transform.forward);Require(Physics.Raycast(ray,out var uiHit,.4f,~0,QueryTriggerInteraction.Collide)&&uiHit.collider==next.GetComponent<Collider>(),"Physical pointer cannot reach Book navigation");slice.SelectCreationBook(CreationBookSection.People);Require((bool)pointer.Invoke(slice,new object[]{1,true,false,next.GetComponent<Collider>(),false}),"Book lost input while tracking absent");var current=(int)typeof(QuestSlice).GetField("bookPage",flags).GetValue(slice);Require(current==0,"Untracked pointer turned page");pointer.Invoke(slice,new object[]{1,true,false,next.GetComponent<Collider>(),true});Require((int)typeof(QuestSlice).GetField("bookPage",flags).GetValue(slice)==1,"Tracked press did not turn page");pointer.Invoke(slice,new object[]{1,true,true,next.GetComponent<Collider>(),true});Require((int)typeof(QuestSlice).GetField("bookPage",flags).GetValue(slice)==1,"Held trigger turned page twice");
   float now=test.Hybrid.time;slice.Simulate(.2f);Require(!test.paused&&test.Hybrid.time>now&&slice.CreationBookOpen,"Opening Book froze simulation");
   slice.ShowCreationBook(false);audio.Invoke(slice,new object[]{true});audio.Invoke(slice,new object[]{false});Require(!root.activeSelf,"Sound back button accidentally opened Book");
   var held=(CarryItem[])typeof(QuestSlice).GetField("held",flags).GetValue(slice);var item=slice.GetComponentInChildren<CreatureHybrid>().GetComponent<CarryItem>();held[1]=item;Require(!slice.ShowCreationBook(true)&&held[1]==item,"Book stole held item");held[1]=null;
   test.paused=true;before=JsonUtility.ToJson(test);Require(slice.ShowCreationBook(true),"Paused Book inaccessible");slice.SelectCreationBook(CreationBookSection.Places);slice.TurnCreationBook(1);Require(JsonUtility.ToJson(test)==before,"Paused Book navigation changed state");Debug.Log("BWVR_CREATION_BOOK_RUNTIME_PASS: starts hidden, exact read-only navigation, all live page layouts fit, tracked edge-only UI input, world-action isolation, held-item protection, audio/back coexistence, running and paused simulation");
  }finally{UnityEngine.Object.DestroyImmediate(outsider);slice.ShowCreationBook(false);panel.SetActive(wasPanel);stateField.SetValue(slice,original);}
 }
}
}
